return-response.set-body:
@{
            return new JObject(
              new JProperty("type", "https://github.com/azure-intelligence-domain/integration-platform/blob/main/docs/problems/platform-token-required.md"),
              new JProperty("title", "Platform Token Required"),
              new JProperty("status", 401),
              new JProperty("detail", "Process and System APIs are called by building blocks only, with an Entra ID token for the intplat-platform-apis application, from a client on the platform's allow-list."),
              new JProperty("instance", context.Request.OriginalUrl.Path)
            ).ToString();
          }
